from pathlib import Path
import json
R=Path(__file__).resolve().parent.parent
style='''@font-face{font-family:Inter;src:url(../assets/inter-400.ttf)}*{box-sizing:border-box}body{margin:0;background:#f5f6f1;color:#222b22;font:15px/1.6 Inter,Arial,sans-serif}header,main,footer{padding:27px 35px}header{background:#222b22;color:white}h1{font-size:30px;line-height:1.2;margin:10px 0}h2{font-size:22px;line-height:1.3}p{max-width:1100px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:30px}.panel{border:1px solid #aeb9a7;background:white;padding:22px;min-width:0}.capture{aspect-ratio:1440/1000;overflow:hidden;border:1px solid #cdd3c6}.pair .capture img{width:100%;height:auto;display:block}.label{font-size:12px;color:#53604c;margin:12px 0}.facts{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:25px 0}.zone{border:1px solid #777;background:#eee;padding:18px;margin:10px 0;text-align:center;font-size:14px}.row{display:flex;gap:12px}.row .zone{flex:1}.muted{color:#555;font-size:13px}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:13px;border-bottom:1px solid #cdd3c6;vertical-align:top}a{color:inherit}nav{display:flex;gap:22px;flex-wrap:wrap}nav a{padding:9px;border:1px solid #aeb9a7}@media(max-width:750px){.pair,.facts{grid-template-columns:1fr}header,main,footer{padding:22px 20px}}'''
refs=[dict(id='ride-home',title='Activity first, facts close by',url='https://theme-ride-demo.myshopify.com/',ref='../../../evidence/ride-home-desktop.jpg',scene='01-home-top',observation='Saved Ride evidence: dark activity masthead, asymmetric action hero, followed by performance merchandise and brand stories.',problem='A recreational buyer needs a relevant activity route before choosing an equipment-specific option.',retained='A clear primary CTA, activity context and contained shopping navigation.',difference='Trailmark opens three named activity pathways and follows with a light factual merchandising area. It avoids relying on action imagery to communicate measurements.',contract='A category navigation and product primitives; C activity bindings and equipment-card facts.'),dict(id='tinker-product',title='Measured facts without implied compatibility',url='https://theme-tinker-demo.myshopify.com/products/craighill-venn-puzzle-stainless-steel?variant=51204750934319',ref='../../../evidence/tinker-product-desktop.jpg',scene='05-product-specs',observation='Saved Tinker evidence: selected mechanical puzzle uses concise dimension tiles beside a conventional purchase area. The saved screenshot has an unloaded gallery; that is an evidence limit.',problem='A buyer needs actual dimensions and clear absent fit information, even when photography is attractive.',retained='Readable dimensions, units and a conventional purchase flow.',difference='Trailmark groups racket length, unstrung mass, grip circumference, supplied use conditions and unconfirmed replacement compatibility. Clothing uses a separate attribute model.',contract='C typed category facts, public projection and unit validation; D source responsibility for compatibility claims.')]
for r in refs:
 page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{r['title']} · Trailmark comparison</title><style>{style}</style><header><div>RESEARCH / ORIGINAL TRAILMARK PROPOSAL</div><h1>{r['title']}</h1><p>Comparable source width: 1440 CSS px · Evidence dated 22 October 2026 · Proposal v1 exported 23 October 2026</p></header><main><div class="pair"><section class="panel"><h2>Shopify reference / saved evidence</h2><p class="label">Desktop 1440 × 1000, DPR 1 · Opening 1000 CSS px from saved capture</p><div class="capture"><img src="{r['ref']}" alt="Saved Shopify reference capture"></div><p><a href="{r['url']}">Public reference URL</a></p><p>{r['observation']}</p></section><section class="panel"><h2>Trailmark / {r['scene']}</h2><p class="label">Desktop 1440 × 1000, DPR 1 · Opening 1000 CSS px from full-page proposal</p><div class="capture"><img src="../images/{r['scene']}-desktop.png" alt="Trailmark original scene"></div><p><a href="../source/{r['scene']}.html">Editable responsive proposal</a></p><p>{r['difference']}</p></section></div><table><tr><th>User problem</th><td>{r['problem']}</td></tr><tr><th>Retained convention</th><td>{r['retained']}</td></tr><tr><th>Original difference</th><td>{r['difference']}</td></tr><tr><th>Required contract</th><td>{r['contract']}</td></tr></table><p class="muted">Direct saved observation and design interpretation are separate. Read-only web retrieval refreshed Ride’s public listing and fins collection on 22 October; Tinker’s selected product/decor page was unavailable through the web tool, so Tinker claims remain confined to saved evidence. No Shopify mutation, purchase, conformance or conversion result is claimed.</p><nav><a href="index.html">All comparisons</a><a href="../index.html">Storybook</a></nav></main></html>'''
 (R/'comparisons'/f'{r["id"]}.html').write_text(page)
neutral={
'home':(['Activity choice before catalog','Three pathways: court / movement / clothing','Measured equipment shelf','How to choose / conditions / support'],['Campaign and silhouette imagery','Apparel collections by silhouette','Outfit product links','Fabric and care editorial']),
'collection':(['Activity breadcrumb + equipment categories','Category-specific measured facet rail','Cards: activity + length/weight + INR','Mobile: compact technical rows'],['Apparel category and silhouette tabs','Size / color / price facets','Cards: garment image + size/color + INR','Mobile: outfit-oriented product cards']),
'product':(['Equipment gallery + context','Model/grip measurement + availability','Length / weight / conditions / unknown fit','Independent accessories / policy'],['Garment gallery + editorial image','Named color / clothing size + availability','Garment measurement / fabric / care','Independent outfit links / policy'])}
neutralStyle=style+'body{background:#f7f7f7;color:#222}header{background:#222;color:white}.panel{border-color:#aaa}.muted,.label{color:#555}'
for key,(equipment,apparel) in neutral.items():
 panels=''
 for name,zones in [('Equipment mission',equipment),('Apparel mission',apparel)]:
  panels+=f'<section class="panel"><h2>{name}</h2><p class="muted">Original neutral structural abstraction · {key}</p>'+''.join(f'<div class="zone">{z}</div>'for z in zones)+'</section>'
 (R/'comparisons'/f'neutral-{key}.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Neutral {key} structure</title><style>{neutralStyle}</style><header><div>STRUCTURE / BRAND, COLOR AND PHOTOGRAPHY SUPPRESSED</div><h1>Different questions. Different page hierarchy.</h1><p>Original abstraction of Trailmark and the existing apparel proposal. These diagrams are expert synthesis, not modified Shopify captures or production render evidence.</p></header><main><div class="pair">{panels}</div><p>Shared controls remain familiar. The equipment mission uses activity, dimensions, grip and conditions; the apparel mission uses silhouette, garment size, fabric and outfit context.</p><nav><a href="index.html">All comparisons</a><a href="../source/03-collection.html?neutral=1">Neutral Trailmark source render</a></nav></main></html>')
(R/'comparisons/index.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trailmark comparisons</title><style>{style}</style><header><h1>Trailmark / Research and task structure</h1><p>Saved primary evidence and original design interpretations. No conversion or full-accessibility claim.</p></header><main><h2>Two attributable Shopify references</h2>'+''.join(f'<p><a href="{r["id"]}.html">{r["title"]}</a></p>'for r in refs)+'<h2>Neutral portfolio structures</h2>'+''.join(f'<p><a href="neutral-{k}.html">Neutral {k} comparison</a></p>'for k in neutral)+'<p><a href="../source/attribute-model.html">Interactive category attribute and recovery sheet</a></p><p><a href="stress-audit.json">Responsive stress audit</a></p><p><a href="../index.html">Storybook</a></p></main></html>')
(R/'comparisons/references.json').write_text(json.dumps(dict(researchDate='2026-10-22',proposalDate='2026-10-23',references=refs,primaryRefresh=[dict(url='https://themes.shopify.com/themes/ride/presets/ride',status='read-only web retrieval; listing accessible'),dict(url='https://theme-ride-demo.myshopify.com/collections/fins',status='read-only web retrieval; collection accessible'),dict(url='https://theme-tinker-demo.myshopify.com/products/craighill-venn-puzzle-stainless-steel?variant=51204750934319',status='web retrieval unavailable; saved evidence used')],limits=['Saved screenshot reference, not a new interactive audit','Unloaded image in saved Tinker product capture','No checkout completion, user study, conversion or conformance claim']),indent=2))
print('Two side-by-side reference comparisons and three neutral structural comparisons ready.')
